# ScreenCycle - created by Luka LAURENT.
# The whole program is in this file: Windows PowerShell compiles it in memory at start-up, so it runs even on PCs
# where Smart App Control blocks unsigned .exe files.
#
#   Normal start:     double-click ScreenCycle.cmd (one folder up), or the ScreenCycle shortcut
#   From a shell:     powershell -ExecutionPolicy Bypass -File ScreenCycle.ps1 [--settings] [--no-start] [--exit] [--welcome]
#
# This file is generated by build.ps1 - edit the sources in src\ instead.

$ErrorActionPreference = 'Stop'
$scriptPath = $MyInvocation.MyCommand.Path

$sources = @(
##SOURCES##
)

try {
    Add-Type -AssemblyName System.Windows.Forms, System.Drawing
    $provider = New-Object Microsoft.CSharp.CSharpCodeProvider
    $cp = New-Object System.CodeDom.Compiler.CompilerParameters
    $cp.GenerateInMemory = $true
    $cp.GenerateExecutable = $false
    $cp.CompilerOptions = '/optimize+'
    foreach ($r in 'System.dll','System.Core.dll','System.Drawing.dll','System.Windows.Forms.dll','System.Xml.dll','System.Management.dll','System.Web.Extensions.dll') {
        [void]$cp.ReferencedAssemblies.Add($r)
    }
    $result = $provider.CompileAssemblyFromSource($cp, [string[]]$sources)
    if ($result.Errors.HasErrors) {
        $msg = ($result.Errors | Where-Object { -not $_.IsWarning } | Select-Object -First 5 | ForEach-Object { $_.ToString() }) -join "`n"
        throw "ScreenCycle could not be compiled:`n$msg"
    }
    $program = $result.CompiledAssembly.GetType('ScreenCycle.Program')
    [void]$program.GetMethod('RunFromScript').Invoke($null, @($scriptPath, [string[]]$args))
}
catch {
    $err = $_.Exception
    while ($err.InnerException) { $err = $err.InnerException }
    try {
        $logDir = Join-Path $env:LOCALAPPDATA 'ScreenCycle'
        New-Item -ItemType Directory -Force $logDir | Out-Null
        Add-Content -Path (Join-Path $logDir 'ScreenCycle.log') -Value ((Get-Date -Format 'yyyy-MM-dd HH:mm:ss.fff') + ' ERROR launcher: ' + $err.ToString())
    } catch { }
    [System.Windows.Forms.MessageBox]::Show($err.Message, 'ScreenCycle', 'OK', 'Error') | Out-Null
    exit 1
}
